// Bin status buckets. Seed data and the Mongoose enum disagree (English vs
// Italian), so we match both spellings. Anything not "damaged" counts as
// operational; "reported" bins are the only segnalazione signal reachable
// from the frontend (a /report/create call flips the bin to SEGNALATO).
const DAMAGED_STATUSES  = new Set(['MANUTENZIONE', 'SEGNALATO', 'GUASTO', 'BROKEN', 'DAMAGED', 'MAINTENANCE', 'OUT_OF_ORDER']);
const REPORTED_STATUSES = new Set(['SEGNALATO', 'REPORTED']);
const isDamaged  = (s) => DAMAGED_STATUSES.has(String(s || '').toUpperCase());
const isReported = (s) => REPORTED_STATUSES.has(String(s || '').toUpperCase());

// ── Point-in-polygon (ray casting) to assign a coordinate to a circoscrizione ─
function pointInRing([x, y], ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    if (((yi > y) !== (yj > y)) && (x < ((xj - xi) * (y - yi)) / (yj - yi) + xi)) {
      inside = !inside;
    }
  }
  return inside;
}
function pointInFeature(pt, geometry) {
  const polys = geometry.type === 'MultiPolygon' ? geometry.coordinates : [geometry.coordinates];
  for (const poly of polys) {
    if (pointInRing(pt, poly[0])) {
      let inHole = false;
      for (let k = 1; k < poly.length; k++) {
        if (pointInRing(pt, poly[k])) { inHole = true; break; }
      }
      if (!inHole) return true;
    }
  }
  return false;
}
// Returns the circoscrizione name containing (lat, lon), or null.
function zoneForCoord(lat, lon) {
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) return null;
  for (const f of CIRCOSCRIZIONI.features) {
    if (pointInFeature([lon, lat], f.geometry)) return f.properties.name;
  }
  return null;
}

// True when a center/bin marker visually covers the given screen point. Markers
// are drawn above the event circles and the neighbourhood zones, so when one
// sits on the clicked spot it should win the interaction (its own popup handles
// the click) and the underlying event/zone handler must stand down. When no
// marker is there, the click falls through to the event/zone as usual.
function markerCoversPoint(map, items, point) {
  if (!map || !point || !Array.isArray(items)) return false;
  const HALF_W = 16, ABOVE = 42, BELOW = 4; // default maplibre pin, anchored at its tip
  for (const it of items) {
    const lat = Number(it?.coordinates?.lat);
    const lng = Number(it?.coordinates?.lng);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) continue;
    const p = map.project([lng, lat]);
    if (point.x >= p.x - HALF_W && point.x <= p.x + HALF_W &&
        point.y >= p.y - ABOVE && point.y <= p.y + BELOW) {
      return true;
    }
  }
  return false;
}

// ── Web map (admin is web-only so we only need this variant) ─────────────────
function WebMap({
  targetCenter, styleUrl, centers, onCenterClick, onZoneClick,
  placingMode = false, onPlaceClick, pendingCoord = null, adminBins = [], binColor = '#9E9E9E',
  events = [], eventPlacing = false, onEventPlaceClick, onEventRightClick, onEventClick, previewCircle = null,
}) {
  const mapRef       = useRef(null);
  const containerRef = useRef(null);
  const style        = styleUrl || OFM_STYLE_FALLBACK;
  const [maplibreInstance, setMaplibreInstance] = useState(null);
  const [mapReady, setMapReady] = useState(false);
  const markersRef   = useRef([]);

  // Keep the latest zone-click callback reachable from the once-only map setup
  const onZoneClickRef = useRef(onZoneClick);
  useEffect(() => { onZoneClickRef.current = onZoneClick; }, [onZoneClick]);

  // Latest centers/bins, reachable from the once-only fill click handlers so they
  // can yield to a bin/center marker sitting on top of the clicked spot.
  const centersRef = useRef(centers);
  useEffect(() => { centersRef.current = centers; }, [centers]);
  const adminBinsRef = useRef(adminBins);
  useEffect(() => { adminBinsRef.current = adminBins; }, [adminBins]);
  const markedItems = () => [...(centersRef.current || []), ...(adminBinsRef.current || [])];

  // Keep placing-phase state/callbacks reachable from once-only event handlers
  const placingModeRef  = useRef(placingMode);
  useEffect(() => { placingModeRef.current = placingMode; }, [placingMode]);
  const onPlaceClickRef = useRef(onPlaceClick);
  useEffect(() => { onPlaceClickRef.current = onPlaceClick; }, [onPlaceClick]);

  // Event placing / click callbacks reachable from once-only event handlers
  const eventPlacingRef     = useRef(eventPlacing);
  useEffect(() => { eventPlacingRef.current = eventPlacing; }, [eventPlacing]);
  const onEventPlaceClickRef = useRef(onEventPlaceClick);
  useEffect(() => { onEventPlaceClickRef.current = onEventPlaceClick; }, [onEventPlaceClick]);
  const onEventRightClickRef = useRef(onEventRightClick);
  useEffect(() => { onEventRightClickRef.current = onEventRightClick; }, [onEventRightClick]);
  const onEventClickRef      = useRef(onEventClick);
  useEffect(() => { onEventClickRef.current = onEventClick; }, [onEventClick]);

  const pendingMarkerRef    = useRef(null);
  const binMarkersRef       = useRef([]);
  const eventLabelsRef      = useRef([]);

  useEffect(() => {
    const link = document.createElement('link');
    link.rel  = 'stylesheet';
    link.href = 'https://unpkg.com/maplibre-gl@4/dist/maplibre-gl.css';
    document.head.appendChild(link);

    // Styling for the circoscrizione name label shown on hover
    const labelStyle = document.createElement('style');
    labelStyle.textContent = `
      .circ-popup .maplibregl-popup-content {
        padding: 3px 9px; background: #fff;
        border: 1.5px solid #000; border-radius: 6px;
        box-shadow: 0 2px 6px rgba(0,0,0,0.3);
        font-family: Arial, sans-serif; font-size: 13px;
        font-weight: 700; color: #111; white-space: nowrap;
      }
      .circ-popup .maplibregl-popup-tip { display: none; }
    `;
    document.head.appendChild(labelStyle);

    import('maplibre-gl').then((mod) => {
      if (!containerRef.current) return;
      const maplibregl = mod.default ?? mod;
      setMaplibreInstance(maplibregl);
      const map = new maplibregl.Map({
        container: containerRef.current,
        style,
        center: [DEFAULT_CENTER.lon, DEFAULT_CENTER.lat],
        zoom: DEFAULT_ZOOM,
        attributionControl: true,
      });
      mapRef.current = map;

      // ── Draw the circoscrizioni of Trento (OSM boundaries) ──────────────────
      map.on('load', () => {
        if (map.getSource('circoscrizioni')) return;
        map.addSource('circoscrizioni', {
          type: 'geojson',
          data: CIRCOSCRIZIONI,
          generateId: true, // needed for feature-state hover highlight
        });
        // Subtle fill that brightens on hover
        map.addLayer({
          id: 'circ-fill',
          type: 'fill',
          source: 'circoscrizioni',
          paint: {
            'fill-color': PRIMARY,
            'fill-opacity': [
              'case', ['boolean', ['feature-state', 'hover'], false], 0.30, 0.06,
            ],
          },
        });
        // Black border line
        map.addLayer({
          id: 'circ-line',
          type: 'line',
          source: 'circoscrizioni',
          paint: { 'line-color': '#000000', 'line-width': 2 },
        });

        // Name label that follows the cursor while hovering a zone
        const labelPopup = new maplibregl.Popup({
          closeButton: false,
          closeOnClick: false,
          anchor: 'left',
          offset: 14,
          className: 'circ-popup',
        });
        let hoveredId = null;
        map.on('mousemove', 'circ-fill', (e) => {
          if (!e.features.length) return;
          map.getCanvas().style.cursor = 'pointer';
          if (hoveredId !== null) {
            map.setFeatureState({ source: 'circoscrizioni', id: hoveredId }, { hover: false });
          }
          hoveredId = e.features[0].id;
          map.setFeatureState({ source: 'circoscrizioni', id: hoveredId }, { hover: true });
          labelPopup.setLngLat(e.lngLat).setText(e.features[0].properties.name).addTo(map);
        });
        map.on('mouseleave', 'circ-fill', () => {
          map.getCanvas().style.cursor = '';
          if (hoveredId !== null) {
            map.setFeatureState({ source: 'circoscrizioni', id: hoveredId }, { hover: false });
          }
          hoveredId = null;
          labelPopup.remove();
        });

        // Right-click a neighbourhood → open its statistics popup, but ONLY when
        // there is nothing else on it: if an event circle sits under the cursor
        // the event takes over (handled by the events-fill click below).
        map.on('contextmenu', 'circ-fill', (e) => {
          if (!e.features.length) return;
          if (placingModeRef.current || eventPlacingRef.current) return;
          // A bin/center marker on this spot is a level above the zone → it wins.
          if (markerCoversPoint(map, markedItems(), e.point)) return;
          const evHit = map.queryRenderedFeatures(e.point, { layers: ['events-fill'] });
          if (evHit.length) return;            // an event is here → show the event, not the zone
          onZoneClickRef.current?.(e.features[0].properties.name);
        });

        // ── Recycling events: translucent yellow circle + black outline ───────
        map.addSource('events', { type: 'geojson', data: { type: 'FeatureCollection', features: [] } });
        map.addLayer({
          id: 'events-fill', type: 'fill', source: 'events',
          paint: { 'fill-color': EVENT_FILL, 'fill-opacity': 0.35 },
        });
        map.addLayer({
          id: 'events-line', type: 'line', source: 'events',
          paint: { 'line-color': EVENT_OUTLINE, 'line-width': 2 },
        });
        // Preview circle while configuring a new/edited event (no fill clicks).
        map.addSource('event-preview', { type: 'geojson', data: { type: 'FeatureCollection', features: [] } });
        map.addLayer({
          id: 'event-preview-fill', type: 'fill', source: 'event-preview',
          paint: { 'fill-color': EVENT_FILL, 'fill-opacity': 0.30 },
        });
        map.addLayer({
          id: 'event-preview-line', type: 'line', source: 'event-preview',
          paint: { 'line-color': EVENT_OUTLINE, 'line-width': 2, 'line-dasharray': [2, 1] },
        });

        // Admin: right-click an event circle → modify it (not while placing).
        map.on('contextmenu', 'events-fill', (e) => {
          if (!e.features.length) return;
          if (placingModeRef.current || eventPlacingRef.current) return;
          // A bin/center marker on this spot is a level above the event → it wins.
          if (markerCoversPoint(map, markedItems(), e.point)) return;
          e.preventDefault?.();
          e.originalEvent?.preventDefault?.();
          onEventRightClickRef.current?.(e.features[0].properties.id);
        });
        // Citizen (and generic): left-click an event circle → view its details.
        map.on('click', 'events-fill', (e) => {
          if (!e.features.length) return;
          if (placingModeRef.current || eventPlacingRef.current) return; // placing takes priority
          // A bin/center marker on this spot is a level above the event → it wins.
          if (markerCoversPoint(map, markedItems(), e.point)) return;
          onEventClickRef.current?.(e.features[0].properties.id);
        });
        map.on('mouseenter', 'events-fill', () => {
          if (!placingModeRef.current && !eventPlacingRef.current) map.getCanvas().style.cursor = 'pointer';
        });
        map.on('mouseleave', 'events-fill', () => {
          if (!placingModeRef.current && !eventPlacingRef.current) map.getCanvas().style.cursor = '';
        });

        setMapReady(true);
      });
    });

    return () => {
      mapRef.current?.remove();
      mapRef.current = null;
      if (document.head.contains(link)) document.head.removeChild(link);
      if (document.head.contains(labelStyle)) document.head.removeChild(labelStyle);
    };
  }, [style]);

  useEffect(() => {
    if (!targetCenter || !mapRef.current) return;
    mapRef.current.flyTo({ center: [targetCenter[1], targetCenter[0]], zoom: 15 });
  }, [targetCenter]);

  useEffect(() => {
    if (!mapRef.current || !maplibreInstance) return;
    markersRef.current.forEach(m => m.remove());
    markersRef.current = [];
    centers.forEach(center => {
      if (!center.coordinates) return;
      const marker = new maplibreInstance.Marker({ color: PRIMARY })
        .setLngLat([Number(center.coordinates.lng), Number(center.coordinates.lat)])
        .addTo(mapRef.current);
      const popupHtml = `
        <div style="font-family:Arial,sans-serif;padding:5px;cursor:pointer;" id="popup-click-${center._id}">
          <h3 style="color:${PRIMARY};margin:0 0 4px 0;text-decoration:underline;">${center.name}</h3>
          <p style="margin:0;font-size:12px;color:#666;">${center.address || ''}</p>
          <p style="margin:4px 0 0 0;font-size:11px;color:${PRIMARY};font-weight:bold;">👉 Clicca per ottenere maggiori informazioni</p>
        </div>`;
      const popup = new maplibreInstance.Popup({ offset: 25 }).setHTML(popupHtml);
      popup.once('open', () => {
        setTimeout(() => {
          const el = document.getElementById(`popup-click-${center._id}`);
          if (el) el.onclick = () => onCenterClick(center);
        }, 50);
      });
      marker.setPopup(popup);
      markersRef.current.push(marker);
    });
  }, [centers, maplibreInstance]);

  // ── Placing phase: left-click places a bin, middle-button drag pans ──────────
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !maplibreInstance) return;

    // Left click → notify the parent with the clicked coordinate. The bin/center
    // placing phase and the event-creation phase share the same gesture; the
    // active mode decides which callback fires.
    const placeHandler = (e) => {
      const coord = { lat: e.lngLat.lat, lng: e.lngLat.lng };
      if (placingModeRef.current) onPlaceClickRef.current?.(coord);
      else if (eventPlacingRef.current) onEventPlaceClickRef.current?.(coord);
    };

    // Middle-mouse-button drag panning (the default left-drag pan is disabled
    // while placing so a left click registers as a placement instead)
    const isPlacing = () => placingModeRef.current || eventPlacingRef.current;
    let panning = false, lastX = 0, lastY = 0;
    const canvas = map.getCanvas();
    const onMouseDown = (e) => {
      if (!isPlacing() || e.button !== 1) return;
      panning = true; lastX = e.clientX; lastY = e.clientY;
      e.preventDefault();
    };
    const onMouseMove = (e) => {
      if (!panning) return;
      const dx = e.clientX - lastX, dy = e.clientY - lastY;
      lastX = e.clientX; lastY = e.clientY;
      map.panBy([-dx, -dy], { duration: 0 });
    };
    const onMouseUp = () => { panning = false; };
    // Suppress the browser middle-click autoscroll while placing
    const onAux = (e) => { if (isPlacing() && e.button === 1) e.preventDefault(); };

    map.on('click', placeHandler);
    canvas.addEventListener('mousedown', onMouseDown);
    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);
    canvas.addEventListener('auxclick', onAux);

    return () => {
      map.off('click', placeHandler);
      canvas.removeEventListener('mousedown', onMouseDown);
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
      canvas.removeEventListener('auxclick', onAux);
    };
  }, [maplibreInstance]);

  // Toggle the native left-drag pan + cursor when entering/leaving placing mode
  // (bin/center placing OR event creation both use the left-click-to-place gesture)
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !maplibreInstance) return;
    if (placingMode || eventPlacing) {
      map.dragPan.disable();
      map.getCanvas().style.cursor = 'crosshair';
    } else {
      map.dragPan.enable();
      map.getCanvas().style.cursor = '';
    }
  }, [placingMode, eventPlacing, maplibreInstance]);

  // ── Draw the recycling-event circles + a centred name label per event ────────
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !mapReady || !maplibreInstance) return;
    map.getSource('events')?.setData(eventsToFeatureCollection(events));

    // Name labels: a styled marker pinned at each event's centre.
    eventLabelsRef.current.forEach(m => m.remove());
    eventLabelsRef.current = [];
    (events || []).forEach((e) => {
      const lat = Number(e?.coordinates?.lat);
      const lng = Number(e?.coordinates?.lng);
      if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;
      const el = document.createElement('div');
      el.textContent = e.name || '';
      el.style.cssText =
        'font-family:Arial,sans-serif;font-size:13px;font-weight:700;color:#000;' +
        'text-shadow:0 0 3px #fff,0 0 3px #fff,0 0 3px #fff;white-space:nowrap;pointer-events:none;';
      const marker = new maplibreInstance.Marker({ element: el })
        .setLngLat([lng, lat])
        .addTo(map);
      eventLabelsRef.current.push(marker);
    });
  }, [events, mapReady, maplibreInstance]);

  // Live preview circle while configuring a new/edited event.
  useEffect(() => {
    const map = mapRef.current;
    if (!map || !mapReady || !maplibreInstance) return;
    const src = map.getSource('event-preview');
    if (!src) return;
    if (previewCircle && Number(previewCircle.radius) > 0) {
      src.setData({
        type: 'FeatureCollection',
        features: [{
          type: 'Feature', properties: {},
          geometry: circlePolygon(previewCircle.lat, previewCircle.lng, Number(previewCircle.radius)),
        }],
      });
    } else {
      src.setData({ type: 'FeatureCollection', features: [] });
    }
  }, [previewCircle, mapReady, maplibreInstance]);

  // Marker for the coordinate currently being configured in the popup
  useEffect(() => {
    if (!mapRef.current || !maplibreInstance) return;
    if (pendingMarkerRef.current) { pendingMarkerRef.current.remove(); pendingMarkerRef.current = null; }
    if (pendingCoord) {
      pendingMarkerRef.current = new maplibreInstance.Marker({ color: '#1565C0' })
        .setLngLat([pendingCoord.lng, pendingCoord.lat])
        .addTo(mapRef.current);
    }
  }, [pendingCoord, maplibreInstance]);

  // Markers for the bins placed on the map (grey). The popup is intentionally
  // minimal: only the bin name, the waste types it accepts and the connected
  // collection center — nothing more.
  useEffect(() => {
    if (!mapRef.current || !maplibreInstance) return;
    binMarkersRef.current.forEach(m => m.remove());
    binMarkersRef.current = [];
    // Lookup table center id → name so we can show the connected center.
    const centersById = {};
    (centers || []).forEach(c => { if (c?._id) centersById[String(c._id)] = c.name; });
    (adminBins || []).forEach(bin => {
      const lat = Number(bin?.coordinates?.lat);
      const lng = Number(bin?.coordinates?.lng);
      if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;
      const types = (bin.wasteTypes?.length ? bin.wasteTypes : [bin.wasteType])
        .filter(Boolean).join(', ');
      const centerName = bin.centerId ? (centersById[String(bin.centerId)] || null) : null;
      const marker = new maplibreInstance.Marker({ color: binColor })
        .setLngLat([lng, lat])
        .addTo(mapRef.current);
      const popup = new maplibreInstance.Popup({ offset: 25 }).setHTML(`
        <div style="font-family:Arial,sans-serif;padding:5px;min-width:170px;">
          <h3 style="color:#444;margin:0 0 4px 0;">${bin.name || 'Bidone'}</h3>
          <p style="margin:0;font-size:12px;color:${binColor};font-weight:bold;">${types || '—'}</p>
          <p style="margin:6px 0 0 0;font-size:12px;color:#666;">🏢 ${centerName || 'Nessun centro collegato'}</p>
        </div>`);
      marker.setPopup(popup);
      binMarkersRef.current.push(marker);
    });
  }, [adminBins, maplibreInstance, binColor, centers]);

  return (
    <div
      ref={containerRef}
      style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, width: '100%', height: '100%', zIndex: 0 }}
    />
  );
}

// ── Custom dropdown for selecting a waste type (web admin) ────────────────────
function WasteDropdown({ value, options, placeholder, onSelect }) {
  const [open, setOpen] = useState(false);
  return (
    <View style={[styles.ddWrap, open && { zIndex: 1000 }]}>
      <TouchableOpacity style={styles.ddBtn} activeOpacity={0.7} onPress={() => setOpen(o => !o)}>
        <Text style={[styles.ddBtnText, !value && styles.ddPlaceholder]} numberOfLines={1}>
          {value || placeholder}
        </Text>
        <Text style={styles.ddArrow}>{open ? '▲' : '▼'}</Text>
      </TouchableOpacity>
      {open && (
        <View style={styles.ddList}>
          <ScrollView style={{ maxHeight: 160 }} nestedScrollEnabled showsVerticalScrollIndicator={false}>
            {options.length === 0 ? (
              <Text style={styles.ddEmpty}>—</Text>
            ) : options.map(opt => (
              <TouchableOpacity
                key={opt}
                style={styles.ddItem}
                activeOpacity={0.7}
                onPress={() => { onSelect(opt); setOpen(false); }}
              >
                <Text style={styles.ddItemText}>{opt}</Text>
              </TouchableOpacity>
            ))}
          </ScrollView>
        </View>
      )}
    </View>
  );
}


// ── Main screen ───────────────────────────────────────────────────────────────
export default function HomeAdminScreen() {
  const router = useRouter();

  // Mobile guard — alert once on mount
  useEffect(() => {
    if (Platform.OS !== 'web') {
      Alert.alert(
        'Accesso non disponibile',
        'Admin mode can be reached only via Web, sorry! go on a computer please!',
        [{ text: 'OK' }]
      );
    }
  }, []);

  const [searchQuery,    setSearchQuery]    = useState('');
  const [searchResults,  setSearchResults]  = useState([]);
  const [selectedCenter, setSelectedCenter] = useState(null);
  const [mapCenter,      setMapCenter]      = useState(null);
  const [searchError,    setSearchError]    = useState(false);
  const [mapStyleUrl,    setMapStyleUrl]    = useState(OFM_STYLE_FALLBACK);
  const [centers,        setCenters]        = useState([]);
  const [avatarUri,      setAvatarUri]      = useState(null);

  // Dropdown menus
  const [operatorsOpen, setOperatorsOpen] = useState(true);
  const [citizensOpen,  setCitizensOpen]  = useState(true);
  const [operators,     setOperators]     = useState([]);
  const [citizens,      setCitizens]      = useState([]);

  // Card visibility
  const [showInfoCard, setShowInfoCard] = useState(false); // logo / version card

  // Per-circoscrizione bin aggregates + which zone's stats popup is open
  const [binStatsByZone, setBinStatsByZone] = useState({});
  const [statsZone,      setStatsZone]      = useState(null);

  // ── Add-bin / add-center placing phase ───────────────────────────────────────
  const [placingMode,  setPlacingMode]  = useState(false);     // toolbar btn #2
  const [pendingCoord, setPendingCoord] = useState(null);      // {lat,lng} being configured
  const [creationType, setCreationType] = useState(null);      // null | 'bin' | 'center'
  const [adminBins,    setAdminBins]    = useState([]);        // bins shown as markers
  const [wasteOptions, setWasteOptions] = useState([]);        // selectable waste types

  // Bins are always shown as grey markers on the map.
  const binColor = '#9E9E9E';

  // ── Bin popup form state ─────────────────────────────────────────────────────
  const [binName,       setBinName]       = useState('');
  const [binAddress,    setBinAddress]    = useState('');
  const [binWasteTypes, setBinWasteTypes] = useState(['']);    // index 0 = primary
  const [binCenterId,   setBinCenterId]   = useState('');      // selected center (optional)
  const [addrLoading,   setAddrLoading]   = useState(false);
  const [savingBin,     setSavingBin]     = useState(false);

  // ── Center popup form state ──────────────────────────────────────────────────
  const [centerName,    setCenterName]    = useState('');
  const [centerAddress, setCenterAddress] = useState('');
  const [openH,         setOpenH]         = useState('');      // opening hour   HH
  const [openM,         setOpenM]         = useState('');      // opening minute MM
  const [closeH,        setCloseH]        = useState('');      // closing hour   HH
  const [closeM,        setCloseM]        = useState('');      // closing minute MM
  const [centerAddrLoading, setCenterAddrLoading] = useState(false);
  const [savingCenter,  setSavingCenter]  = useState(false);

  // ── Recycling-event state ────────────────────────────────────────────────────
  const { mode } = useLocalSearchParams();      // 'createEvent' arrives from Event_management
  const [events,         setEvents]        = useState([]);     // all events (circles on the map)
  const [eventMode,      setEventMode]     = useState(false);  // creation map mode (chrome hidden)
  const [eventCenter,    setEventCenter]   = useState(null);   // {lat,lng} chosen for a new event
  const [editingEventId, setEditingEventId] = useState(null);  // non-null while modifying an event
  const [viewingEvent,   setViewingEvent]  = useState(null);   // event object shown read-only
  const [savingEvent,    setSavingEvent]   = useState(false);

  // Event form fields
  const [evName,       setEvName]       = useState('');
  const [evRadius,     setEvRadius]     = useState('');      // metres, as text
  const [evWasteTypes, setEvWasteTypes] = useState(['']);    // boosted waste types
  const [evBoost,      setEvBoost]      = useState(null);    // 2 | 3 | 5 | 10
  const [evStart,      setEvStart]      = useState(null);    // Date
  const [evEnd,        setEvEnd]        = useState(null);    // Date

  const resetEventForm = () => {
    setEvName('');
    setEvRadius('');
    setEvWasteTypes(['']);
    setEvBoost(null);
    setEvStart(null);
    setEvEnd(null);
    setEditingEventId(null);
  };

  const fetchEvents = useCallback(() => {
    axios.get(`${API_URL}/events/all`)
      .then(r => setEvents(Array.isArray(r.data) ? r.data : []))
      .catch(() => setEvents([]));
  }, []);

  const resetBinForm = () => {
    setBinName('');
    setBinAddress('');
    setBinWasteTypes(['']);
    setBinCenterId('');
  };

  const resetCenterForm = () => {
    setCenterName('');
    setCenterAddress('');
    setOpenH(''); setOpenM(''); setCloseH(''); setCloseM('');
  };

  const fetchAdminBins = useCallback(async () => {
    const token = await AsyncStorage.getItem('token');
    const auth  = { headers: { Authorization: `Bearer ${token}` } };
    try {
      const r = await axios.get(`${API_URL}/admin/bins`, auth);
      setAdminBins(Array.isArray(r.data) ? r.data : []);
    } catch { setAdminBins([]); }
  }, []);

  // Poll the placed bins so status changes made by an admin are seen live by
  // everyone else (markers stay in sync).
  useEffect(() => {
    const id = setInterval(() => { fetchAdminBins(); }, 15000);
    return () => clearInterval(id);
  }, [fetchAdminBins]);

  // Refresh the collection centers (used by the bin marker popups and the
  // "center in this neighbourhood" dropdown).
  const fetchCenters = useCallback(() => {
    axios.get(`${API_URL}/centers/all`)
      .then(r => setCenters(Array.isArray(r.data) ? r.data : []))
      .catch(() => setCenters([]));
  }, []);

  useEffect(() => {
    axios.get(`${API_URL}/ofm/config`)
      .then(r => { if (r.data?.styleUrl) setMapStyleUrl(r.data.styleUrl); })
      .catch(() => {});
    axios.get(`${API_URL}/centers/all`)
      .then(r => setCenters(Array.isArray(r.data) ? r.data : []))
      .catch(() => setCenters([]));

    // Fetch operators and citizens lists (admin-only endpoints)
    AsyncStorage.getItem('token').then(token => {
      const auth = { headers: { Authorization: `Bearer ${token}` } };
      axios.get(`${API_URL}/admin/users?role=operator`, auth)
        .then(r => setOperators(Array.isArray(r.data) ? r.data : []))
        .catch(() => setOperators([]));
      axios.get(`${API_URL}/admin/users?role=user`, auth)
        .then(r => setCitizens(Array.isArray(r.data) ? r.data : []))
        .catch(() => setCitizens([]));

      // Selectable waste types (scannable product categories) + placed bins
      axios.get(`${API_URL}/admin/waste-types`, auth)
        .then(r => setWasteOptions(Array.isArray(r.data) ? r.data : []))
        .catch(() => setWasteOptions([]));
      axios.get(`${API_URL}/admin/bins`, auth)
        .then(r => setAdminBins(Array.isArray(r.data) ? r.data : []))
        .catch(() => setAdminBins([]));
    });
  }, []);

  useFocusEffect(
    useCallback(() => {
      AsyncStorage.getItem('profileAvatarUri').then(uri => setAvatarUri(uri || null));
    }, [])
  );

  // Load the recycling events and keep them in sync (circles on the map).
  useEffect(() => { fetchEvents(); }, [fetchEvents]);
  useEffect(() => {
    const id = setInterval(() => { fetchEvents(); }, 15000);
    return () => clearInterval(id);
  }, [fetchEvents]);

  // Keep the collection centers in sync too, so a center created elsewhere is
  // reflected in the neighbourhood statistics ("Centri di Raccolta") without a
  // page reload.
  useEffect(() => {
    const id = setInterval(() => { fetchCenters(); }, 15000);
    return () => clearInterval(id);
  }, [fetchCenters]);

  // Entering from "Crea nuovo evento di raccolta" starts the event-creation map
  // mode (chrome hidden). The query param is consumed once.
  useEffect(() => {
    if (mode === 'createEvent') {
      closeAllCards();
      resetEventForm();
      setEventCenter(null);
      setEventMode(true);
      router.setParams({ mode: undefined });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mode]);

  // Once centers are known, fetch each center's bins and aggregate them by the
  // circoscrizione the center falls into (point-in-polygon on its coordinates).
  useEffect(() => {
    if (!centers.length && !adminBins.length) return;
    let cancelled = false;

    // Add one bin's contribution to its zone's running totals
    const tally = (agg, zone, b) => {
      if (!zone) return;
      const z = (agg[zone] ||= { total: 0, damaged: 0, reported: 0, sensors: 0 });
      z.total += 1;
      if (isDamaged(b.status))  z.damaged  += 1;
      if (isReported(b.status)) z.reported += 1;
      if (b.sensor && Number(b.sensor.batteryLevel) > 0) z.sensors += 1;
    };

    (async () => {
      const agg = {}; // zoneName -> { total, damaged, reported, sensors }

      // Center bins → zone of the center's coordinates
      await Promise.all(centers.map(async (c) => {
        const zone = zoneForCoord(Number(c?.coordinates?.lat), Number(c?.coordinates?.lng));
        if (!zone) return;
        let bins = [];
        try {
          const r = await axios.get(`${API_URL}/centers/${c._id}`);
          bins = Array.isArray(r.data?.bins) ? r.data.bins : [];
        } catch { /* a single center failing must not break the rest */ }
        bins.forEach((b) => tally(agg, zone, b));
      }));

      // Admin-placed bins → zone of each bin's own coordinates
      (adminBins || []).forEach((b) => {
        const zone = zoneForCoord(Number(b?.coordinates?.lat), Number(b?.coordinates?.lng));
        tally(agg, zone, b);
      });

      if (!cancelled) setBinStatsByZone(agg);
    })();
    return () => { cancelled = true; };
  }, [centers, adminBins]);

  // Build the full statistics object for a zone. Categories with no data in the
  // project/DB are reported as 0 (never invented); population is the exception.
  const statsForZone = (name) => {
    const b = binStatsByZone[name] || { total: 0, damaged: 0, reported: 0, sensors: 0 };
    // Collection centers whose coordinates fall inside this circoscrizione.
    const recyclingCenters = (centers || []).filter(
      (c) => zoneForCoord(Number(c?.coordinates?.lat), Number(c?.coordinates?.lng)) === name
    ).length;
    // Active (not-yet-ended) events located in this circoscrizione.
    const eventsInZone = activeEvents.filter(
      (e) => zoneForCoord(Number(e?.coordinates?.lat), Number(e?.coordinates?.lng)) === name
    ).length;
    return {
      totalBins:        b.total,
      operationalBins:  Math.max(0, b.total - b.damaged),
      activeSensors:    b.sensors,
      recyclingCenters,
      citizens:         ZONE_POPULATION[name] ?? 0,
      operators:        0, // users carry no neighbourhood/geo data
      activeEvents:     eventsInZone,
      segnalazioni:     b.reported, // bins flagged SEGNALATO by /report/create
    };
  };

  // Only events that have not ended are drawn on the map / searchable. Concluded
  // events disappear from the map (still listed in the management screen).
  const activeEvents = events.filter((e) => +new Date(e.endDate) > Date.now());

  // Unified searchable elements: collection centers, bins and (active) events.
  const buildSearchItems = () => {
    const items = [];
    (centers || []).forEach((c) => {
      const lat = Number(c?.coordinates?.lat), lng = Number(c?.coordinates?.lng);
      if (c?.name && Number.isFinite(lat) && Number.isFinite(lng))
        items.push({ key: `c_${c._id}`, type: 'center', name: c.name, lat, lng, subtitle: c.address || 'Centro di raccolta' });
    });
    (adminBins || []).forEach((b) => {
      const lat = Number(b?.coordinates?.lat), lng = Number(b?.coordinates?.lng);
      if (b?.name && Number.isFinite(lat) && Number.isFinite(lng))
        items.push({ key: `b_${b._id}`, type: 'bin', name: b.name, lat, lng, subtitle: b.address || 'Bidone' });
    });
    (activeEvents || []).forEach((e) => {
      const lat = Number(e?.coordinates?.lat), lng = Number(e?.coordinates?.lng);
      if (e?.name && Number.isFinite(lat) && Number.isFinite(lng))
        items.push({ key: `e_${e._id}`, type: 'event', name: e.name, lat, lng, subtitle: 'Evento di raccolta' });
    });
    return items;
  };
  const searchTypeIcon = (type) => (type === 'center' ? '📍' : type === 'bin' ? '🗑️' : '🎪');

  const handleQueryChange = (text) => {
    setSearchQuery(text);
    setSelectedCenter(null);
    setSearchError(false);
    const q = text.trim().toLowerCase();
    if (!q) { setSearchResults([]); return; }
    setSearchResults(buildSearchItems().filter(it => it.name.toLowerCase().includes(q)).slice(0, 6));
  };

  const selectResult = (item) => {
    setSearchQuery(item.name);
    setSelectedCenter(item);
    setSearchResults([]);
  };

  const handleSearch = () => {
    setSearchResults([]);
    setSearchError(false);
    const q = searchQuery.trim().toLowerCase();
    const target = selectedCenter || buildSearchItems().find(it => it.name.toLowerCase() === q);
    if (target) {
      setMapCenter([target.lat, target.lng]);
    } else {
      setSearchError(true);
      setTimeout(() => setSearchError(false), 2500);
    }
  };

  const closeAllCards = () => {
    setShowInfoCard(false);
  };

  // ── Placing-phase handlers ───────────────────────────────────────────────────
  const enterPlacing = () => {
    closeAllCards();
    setPendingCoord(null);
    setCreationType(null);
    resetBinForm();
    resetCenterForm();
    setPlacingMode(true);
  };

  const cancelPlacing = () => {
    setPlacingMode(false);
    setPendingCoord(null);
    setCreationType(null);
    resetBinForm();
    resetCenterForm();
  };

  // Map left-click during placing → open the entity-choice dialog at that point
  const handlePlaceClick = useCallback((coord) => {
    setPendingCoord(coord);
    setCreationType(null);
  }, []);

  // Top-right ✕ of a popup → discard this point, keep selecting a new one
  const closePopup = () => {
    setPendingCoord(null);
    setCreationType(null);
    resetBinForm();
    resetCenterForm();
  };

  // ── Recycling-event handlers ─────────────────────────────────────────────────
  // ✕ during event creation → abort and return to the management screen.
  const cancelEventCreation = () => {
    setEventMode(false);
    setEventCenter(null);
    resetEventForm();
    router.replace('/work');
  };

  // Left-click on the map while creating → set the centre and open the popup.
  // Seed sensible default times (now → +1h) the first time the popup opens.
  const handleEventPlaceClick = useCallback((coord) => {
    setEventCenter(coord);
    setEvStart(prev => {
      if (prev) return prev;
      const s = new Date(); s.setSeconds(0, 0);
      return s;
    });
    setEvEnd(prev => {
      if (prev) return prev;
      const e = new Date(); e.setSeconds(0, 0); e.setHours(e.getHours() + 1);
      return e;
    });
  }, []);

  // Admin right-click on an existing event circle → open it for modification.
  const openEditEvent = useCallback((id) => {
    const ev = events.find(e => String(e._id) === String(id));
    if (!ev) return;
    setViewingEvent(null);
    setEditingEventId(String(ev._id));
    setEvName(ev.name || '');
    setEvRadius(String(ev.radius ?? ''));
    setEvWasteTypes(ev.wasteTypes?.length ? [...ev.wasteTypes] : ['']);
    setEvBoost(ev.boost ?? null);
    setEvStart(ev.startDate ? new Date(ev.startDate) : null);
    setEvEnd(ev.endDate ? new Date(ev.endDate) : null);
    setEventCenter({ lat: Number(ev.coordinates.lat), lng: Number(ev.coordinates.lng) });
  }, [events]);

  // ✕ of the event popup. During creation we keep the map mode and let the admin
  // pick a new point; while editing we just close.
  const closeEventPopup = () => {
    if (editingEventId) {
      setEventCenter(null);
      resetEventForm();
    } else {
      setEventCenter(null);
      resetEventForm();
    }
  };

  // Circoscrizione of the event centre (stored as `area`, like bins/centers).
  const eventZone = eventCenter ? zoneForCoord(eventCenter.lat, eventCenter.lng) : null;

  // Waste-type slots for the event (mirrors the bin waste-type picker).
  const setEvWasteAt = (i, value) =>
    setEvWasteTypes(prev => prev.map((v, idx) => (idx === i ? value : v)));
  const addEvWasteSlot = () =>
    setEvWasteTypes(prev => (prev.length < wasteOptions.length ? [...prev, ''] : prev));
  const optionsForEvSlot = (i) =>
    wasteOptions.filter(opt => !evWasteTypes.some((v, idx) => idx !== i && v === opt));
  const canAddMoreEvWaste =
    evWasteTypes.length < wasteOptions.length && evWasteTypes.every(Boolean);

  const evRadiusNum = Number(evRadius);
  const canSaveEvent =
    evName.trim() !== '' &&
    Number.isFinite(evRadiusNum) && evRadiusNum > 0 &&
    !!evWasteTypes[0] &&
    EVENT_BOOSTS.includes(evBoost) &&
    evStart instanceof Date && !Number.isNaN(evStart.getTime()) &&
    evEnd instanceof Date && !Number.isNaN(evEnd.getTime()) &&
    evEnd.getTime() > evStart.getTime() &&
    !savingEvent;

  const saveEvent = async () => {
    if (!canSaveEvent || !eventCenter) {
      if (evStart && evEnd && evEnd.getTime() <= evStart.getTime()) {
        Alert.alert('Date non valide', 'La fine dell\'evento deve essere successiva all\'inizio.');
      }
      return;
    }
    setSavingEvent(true);
    const token = await AsyncStorage.getItem('token');
    const auth  = { headers: { Authorization: `Bearer ${token}` } };
    const payload = {
      name:        evName.trim(),
      coordinates: eventCenter,
      radius:      evRadiusNum,
      wasteTypes:  evWasteTypes.filter(Boolean),
      boost:       evBoost,
      startDate:   evStart.toISOString(),
      endDate:     evEnd.toISOString(),
      area:        eventZone || undefined,
    };
    try {
      if (editingEventId) {
        await axios.patch(`${API_URL}/events/${editingEventId}`, payload, auth);
        await fetchEvents();
        setEventCenter(null);
        resetEventForm();
      } else {
        await axios.post(`${API_URL}/events`, payload, auth);
        await fetchEvents();
        // Creation complete → leave the creation mode and return to the home map.
        setEventMode(false);
        setEventCenter(null);
        resetEventForm();
        router.replace('/(admin)');
      }
    } catch (e) {
      Alert.alert('Errore', e?.response?.data?.message || 'Impossibile salvare l\'evento. Riprova.');
    } finally {
      setSavingEvent(false);
    }
  };

  const deleteEvent = async () => {
    if (!editingEventId) return;
    setSavingEvent(true);
    const token = await AsyncStorage.getItem('token');
    const auth  = { headers: { Authorization: `Bearer ${token}` } };
    try {
      await axios.delete(`${API_URL}/events/${editingEventId}`, auth);
      await fetchEvents();
      setEventCenter(null);
      resetEventForm();
    } catch {
      Alert.alert('Errore', 'Impossibile eliminare l\'evento. Riprova.');
    } finally {
      setSavingEvent(false);
    }
  };

  // Circoscrizione (neighbourhood) of the clicked point + the centers within it
  const pendingZone = pendingCoord
    ? zoneForCoord(pendingCoord.lat, pendingCoord.lng)
    : null;
  const centersInZone = pendingZone
    ? centers.filter(c =>
        c?.coordinates &&
        zoneForCoord(Number(c.coordinates.lat), Number(c.coordinates.lng)) === pendingZone)
    : [];

  // Shared reverse-geocode helper → returns a display address or null
  const reverseGeocode = async (coord) => {
    const r = await axios.get(`${API_URL}/osm/reverse?lat=${coord.lat}&lon=${coord.lng}`);
    const data = r.data || {};
    let address = data.display_name;
    if (!address && data.address) {
      const a = data.address;
      address = [
        [a.road, a.house_number].filter(Boolean).join(' '),
        a.city || a.town || a.village,
        a.postcode,
      ].filter(Boolean).join(', ');
    }
    return address || null;
  };

  // Reverse-geocode the pointed location into the bin's address field
  const calcAddress = async () => {
    if (!pendingCoord || addrLoading) return;
    setAddrLoading(true);
    try {
      const address = await reverseGeocode(pendingCoord);
      if (address) setBinAddress(address);
      else Alert.alert('Indirizzo non trovato', 'Non è stato possibile calcolare l\'indirizzo di questo punto.');
    } catch {
      Alert.alert('Errore', 'Impossibile calcolare l\'indirizzo. Riprova.');
    } finally {
      setAddrLoading(false);
    }
  };

  // Reverse-geocode the pointed location into the center's address field
  const calcCenterAddress = async () => {
    if (!pendingCoord || centerAddrLoading) return;
    setCenterAddrLoading(true);
    try {
      const address = await reverseGeocode(pendingCoord);
      if (address) setCenterAddress(address);
      else Alert.alert('Indirizzo non trovato', 'Non è stato possibile calcolare l\'indirizzo di questo punto.');
    } catch {
      Alert.alert('Errore', 'Impossibile calcolare l\'indirizzo. Riprova.');
    } finally {
      setCenterAddrLoading(false);
    }
  };

  // Waste-type dropdown helpers
  const setWasteAt = (i, value) =>
    setBinWasteTypes(prev => prev.map((v, idx) => (idx === i ? value : v)));
  const addWasteSlot = () =>
    setBinWasteTypes(prev =>
      prev.length < wasteOptions.length ? [...prev, ''] : prev);
  // Options available for slot i = all types not chosen in the other slots
  const optionsForSlot = (i) =>
    wasteOptions.filter(opt => !binWasteTypes.some((v, idx) => idx !== i && v === opt));
  const canAddMoreWaste =
    binWasteTypes.length < wasteOptions.length && binWasteTypes.every(Boolean);

  const canAddBin =
    binName.trim() !== '' && binAddress.trim() !== '' && !!binWasteTypes[0] && !savingBin;

  const addBin = async () => {
    if (!canAddBin) return;
    setSavingBin(true);
    const token = await AsyncStorage.getItem('token');
    const auth  = { headers: { Authorization: `Bearer ${token}` } };
    try {
      await axios.post(`${API_URL}/admin/bins`, {
        name:        binName.trim(),
        address:     binAddress.trim(),
        coordinates: pendingCoord,
        wasteTypes:  binWasteTypes.filter(Boolean),
        centerId:    binCenterId || null,   // null = no center (status set to GUASTO server-side)
        area:        pendingZone || undefined,
      }, auth);
      closePopup();            // back to the placing phase, pick a new point
      fetchAdminBins();        // refresh the grey markers
    } catch {
      Alert.alert('Errore', 'Impossibile aggiungere il bidone. Riprova.');
    } finally {
      setSavingBin(false);
    }
  };

  // ── Collection-center creation ───────────────────────────────────────────────
  const canAddCenter =
    centerName.trim() !== '' && centerAddress.trim() !== '' && !savingCenter;

  // Build "HH:MM" from the two numeric fields, or null if incomplete/invalid
  const buildTime = (h, m) => {
    if (h === '' && m === '') return null;
    const hh = Number(h), mm = Number(m);
    if (!Number.isInteger(hh) || hh < 0 || hh > 23) return null;
    if (!Number.isInteger(mm) || mm < 0 || mm > 59) return null;
    return `${String(hh).padStart(2, '0')}:${String(mm).padStart(2, '0')}`;
  };

  const addCenter = async () => {
    if (!canAddCenter) return;
    setSavingCenter(true);
    const token = await AsyncStorage.getItem('token');
    const auth  = { headers: { Authorization: `Bearer ${token}` } };

    // Opening hours: only sent if both times are valid, otherwise the server
    // applies the schema default.
    const open  = buildTime(openH, openM);
    const close = buildTime(closeH, closeM);
    const openingHours = (open && close) ? `Lun-Dom ${open}-${close}` : undefined;

    try {
      await axios.post(`${API_URL}/admin/centers`, {
        name:        centerName.trim(),
        address:     centerAddress.trim(),
        area:        pendingZone || 'Altro',
        coordinates: pendingCoord,
        openingHours,
      }, auth);
      closePopup();        // back to the placing phase, pick a new point
      fetchCenters();      // new amaranth marker
      fetchAdminBins();    // auto-assignment may have linked orphan bins
    } catch {
      Alert.alert('Errore', 'Impossibile creare il centro di raccolta. Riprova.');
    } finally {
      setSavingCenter(false);
    }
  };
  //button per la side bar a sinistra 
  const sideButtons = [
    //  REPORT ADMIN
    { id: 0, icon: SegnalazioniImg, label: 'Segnalazioni', onPress: () => router.push('/report_admin') }, 
    { id: 1, icon: AddBinImg, label: 'Posiziona bidone', onPress: () => enterPlacing() },
    { id: 2, icon: ProblemBin, label: 'Centri di raccolta', onPress: () => router.push('/centers/unassigned/bins') },
  ];

  // ── Mobile fallback ──────────────────────────────────────────────────────────
  if (Platform.OS !== 'web') {
    return (
      <View style={styles.mobileFallback}>
        <Text style={styles.mobileMessage}>
          Admin mode can be reached only via Web.{'\n'}Please use a computer.
        </Text>
      </View>
    );
  }

  // ── Web view ─────────────────────────────────────────────────────────────────
  return (
    <View style={styles.container} onStartShouldSetResponder={() => { closeAllCards(); return false; }}>
      <StatusBar style="auto" />

      {/* Map */}
      <WebMap
        targetCenter={mapCenter}
        styleUrl={mapStyleUrl}
        centers={centers}
        onCenterClick={(center) => router.push(`/centers/${center._id}/bins`)}
        onZoneClick={(name) => setStatsZone(name)}
        placingMode={placingMode}
        onPlaceClick={handlePlaceClick}
        pendingCoord={pendingCoord || (eventMode ? eventCenter : null)}
        adminBins={adminBins}
        binColor={binColor}
        events={activeEvents}
        eventPlacing={eventMode}
        onEventPlaceClick={handleEventPlaceClick}
        onEventRightClick={openEditEvent}
        onEventClick={(id) => {
          const ev = events.find(e => String(e._id) === String(id));
          if (ev) setViewingEvent(ev);
        }}
        previewCircle={eventCenter && evRadiusNum > 0
          ? { lat: eventCenter.lat, lng: eventCenter.lng, radius: evRadiusNum }
          : null}
      />

      {/* All standard chrome is hidden while in the bin-placing or event-creation phase */}
      {!placingMode && !eventMode && (<>

      {/* ── Search bar ── */}
      <View style={[styles.searchBarWrapper, { zIndex: 10 }]} pointerEvents="box-none">
        <View style={styles.searchBar}>
          <TouchableOpacity onPress={handleSearch} activeOpacity={0.7}>
            <Text style={styles.searchIcon}>🔍</Text>
          </TouchableOpacity>
          <TextInput
            style={styles.searchInput}
            placeholder="Cerca una location..."
            placeholderTextColor="#9999"
            value={searchQuery}
            onChangeText={handleQueryChange}
            onSubmitEditing={handleSearch}
            returnKeyType="search"
          />
        </View>

        {searchError && (
          <View style={styles.searchErrorBox}>
            <Text style={styles.searchErrorText}>Location not found</Text>
          </View>
        )}

        {searchResults.length > 0 && (
          <View style={styles.resultsDropdown}>
            {searchResults.map((item, i) => (
              <TouchableOpacity
                key={item.key ?? i}
                style={[styles.resultItem, i < searchResults.length - 1 && styles.resultItemBorder]}
                activeOpacity={0.7}
                onPress={() => selectResult(item)}
              >
                <Text style={styles.resultIcon}>{searchTypeIcon(item.type)}</Text>
                <View style={{ flex: 1 }}>
                  <Text style={styles.resultText} numberOfLines={1}>{item.name}</Text>
                  {item.subtitle ? <Text style={styles.resultSubText} numberOfLines={1}>{item.subtitle}</Text> : null}
                </View>
              </TouchableOpacity>
            ))}
          </View>
        )}
      </View>

      {/* ── Left vertical tool bar ── */}
      <View style={[styles.sideBar, { zIndex: 10 }]}>
        {[0, 1, 2].map((i) => (
          <TouchableOpacity
            key={i}
            style={styles.sideButton}
            activeOpacity={0.85}
            onPress={() => sideButtons[i]?.onPress()}
          >
            <Image source={sideButtons[i]?.icon} style={styles.sideButtonIcon} />
          </TouchableOpacity>
        ))}
      </View>

      {/* ── Right panels: Operators + Citizens stacked ── */}
      <View style={styles.rightPanels}>

        {/* Operators */}
        <View style={styles.dropdownCard}>
          <View style={styles.dropdownHeader}>
            <Text style={styles.dropdownTitle}>Operators</Text>
            <TouchableOpacity
              onPress={() => setOperatorsOpen(v => !v)}
              style={styles.dropdownArrowBtn}
              activeOpacity={0.7}
            >
              <Text style={styles.dropdownArrow}>{operatorsOpen ? '▲' : '▼'}</Text>
            </TouchableOpacity>
          </View>
          {operatorsOpen && (
            <ScrollView style={styles.dropdownContent} nestedScrollEnabled showsVerticalScrollIndicator={false}>
              {operators.length === 0 ? (
                <Text style={styles.dropdownEmpty}>_ no operators found</Text>
              ) : operators.map((op, i) => (
                <Text key={op._id ?? i} style={styles.dropdownItem}>
                  {'◆  '}{op.name ?? op.username ?? op.email ?? '—'}
                </Text>
              ))}
            </ScrollView>
          )}
        </View>

        {/* Citizens — sits directly below Operators, follows it */}
        <View style={styles.dropdownCard}>
          <View style={styles.dropdownHeader}>
            <Text style={styles.dropdownTitle}>Citizens</Text>
            <TouchableOpacity
              onPress={() => setCitizensOpen(v => !v)}
              style={styles.dropdownArrowBtn}
              activeOpacity={0.7}
            >
              <Text style={styles.dropdownArrow}>{citizensOpen ? '▲' : '▼'}</Text>
            </TouchableOpacity>
          </View>
          {citizensOpen && (
            <ScrollView style={styles.dropdownContent} nestedScrollEnabled showsVerticalScrollIndicator={false}>
              {citizens.length === 0 ? (
                <Text style={styles.dropdownEmpty}>_ no citizens found</Text>
              ) : citizens.map((c, i) => (
                <Text key={c._id ?? i} style={styles.dropdownItem}>
                  {'◆  '}{c.name ?? c.username ?? c.email ?? '—'}
                </Text>
              ))}
            </ScrollView>
          )}
        </View>

      </View>

      {/* ── Button bar ── */}
      <View style={[styles.buttonBar, { zIndex: 10 }]} pointerEvents="box-none">

        {/* LEFT — User info */}
        <View style={styles.buttonWrapper}>
          <TouchableOpacity
            style={styles.button}
            activeOpacity={0.85}
            onPress={() => { closeAllCards(); router.push('/profile'); }}
          >
            <Image source={avatarUri ? { uri: avatarUri } : UserDefault} style={styles.buttonIcon} />
          </TouchableOpacity>
        </View>

        {/* CENTER — Logo / version */}
        <View style={styles.buttonWrapper}>
          {showInfoCard && (
            <View style={styles.popupCard}>
              <Text style={styles.popupTitle}>Riciclapp</Text>
              <Text style={styles.popupSub}>Version Alpha 1.0.0</Text>
              <Text style={styles.popupSectionLabel}>Developers</Text>
              <Text style={styles.popupLine}>Binco Francesco</Text>
              <Text style={styles.popupLine}>Cortese Riccardo</Text>
              <Text style={styles.popupLine}>Giovagnetti Lorenzo</Text>
            </View>
          )}
          <TouchableOpacity
            style={styles.button}
            activeOpacity={0.85}
            onPress={() => setShowInfoCard(v => !v)}
          >
            <Image source={Logo} style={styles.buttonIcon} />
          </TouchableOpacity>
        </View>

        {/* RIGHT — Recycling event (Eventi di Raccolta) */}
        <View style={styles.buttonWrapper}>
          <TouchableOpacity
            style={styles.button}
            activeOpacity={0.85}
            onPress={() => { closeAllCards(); router.push('/work'); }}
          >
            <Image source={EventImg} style={styles.buttonIcon} />
          </TouchableOpacity>
        </View>

      </View>

      </>)}

      {/* ── Placing phase: hint + cancel + choice dialog + configuration popups ── */}
      {placingMode && (
        <>
          {/* Top hint */}
          {!pendingCoord && (
            <View style={styles.placeHintBox} pointerEvents="none">
              <Text style={styles.placeHintText}>
                Click sulla mappa per scegliere dove creare · rotella per zoom · tasto centrale per spostarti
              </Text>
            </View>
          )}

          {/* Center-bottom ✕ to cancel placing entirely */}
          <View style={styles.placeCancelWrap} pointerEvents="box-none">
            <TouchableOpacity style={styles.placeCancelBtn} activeOpacity={0.85} onPress={cancelPlacing}>
              <Text style={styles.placeCancelTxt}>✕</Text>
            </TouchableOpacity>
          </View>

          {/* Step 1 — choose what to create (darkened background) */}
          {pendingCoord && !creationType && (
            <View style={styles.binOverlay}>
              <TouchableOpacity style={styles.binBackdrop} activeOpacity={1} onPress={() => {}} />
              <View style={styles.choiceCard}>
                <Text style={styles.choiceTitle}>Cosa vuoi creare qui?</Text>
                <View style={styles.choiceBtnRow}>
                  <TouchableOpacity
                    style={styles.choiceBtn}
                    activeOpacity={0.85}
                    onPress={() => setCreationType('bin')}
                  >
                    <Text style={styles.choiceBtnIcon}>🗑️</Text>
                    <Text style={styles.choiceBtnTxt}>Bidone</Text>
                  </TouchableOpacity>
                  <TouchableOpacity
                    style={styles.choiceBtn}
                    activeOpacity={0.85}
                    onPress={() => setCreationType('center')}
                  >
                    <Text style={styles.choiceBtnIcon}>🏢</Text>
                    <Text style={styles.choiceBtnTxt}>Centro di Raccolta</Text>
                  </TouchableOpacity>
                </View>
                <TouchableOpacity style={styles.choiceCancel} activeOpacity={0.7} onPress={closePopup}>
                  <Text style={styles.choiceCancelTxt}>Annulla</Text>
                </TouchableOpacity>
              </View>
            </View>
          )}

          {/* Step 2a — bin configuration popup */}
          {pendingCoord && creationType === 'bin' && (
            <View style={styles.binOverlay}>
              <TouchableOpacity style={styles.binBackdrop} activeOpacity={1} onPress={() => {}} />
              <View style={styles.binCard}>
                {/* Header */}
                <View style={styles.binHeader}>
                  <Text style={styles.binTitle}>Nuovo cassone</Text>
                  <TouchableOpacity style={styles.binCloseBtn} activeOpacity={0.7} onPress={closePopup}>
                    <Text style={styles.binCloseTxt}>✕</Text>
                  </TouchableOpacity>
                </View>

                <ScrollView style={{ maxHeight: 460 }} showsVerticalScrollIndicator={false}>
                  {/* Name */}
                  <Text style={styles.binLabel}>Nome del bidone</Text>
                  <TextInput
                    style={styles.binInput}
                    placeholder="Es. Bidone Piazza Duomo"
                    placeholderTextColor="#999"
                    value={binName}
                    onChangeText={setBinName}
                  />

                  {/* Address + calculate button */}
                  <Text style={styles.binLabel}>Indirizzo</Text>
                  <View style={styles.binAddressRow}>
                    <TextInput
                      style={[styles.binInput, { flex: 1, marginBottom: 0 }]}
                      placeholder="Indirizzo del bidone"
                      placeholderTextColor="#999"
                      value={binAddress}
                      onChangeText={setBinAddress}
                    />
                    <TouchableOpacity
                      style={styles.binCalcBtn}
                      activeOpacity={0.8}
                      onPress={calcAddress}
                      disabled={addrLoading}
                    >
                      <Text style={styles.binCalcTxt}>{addrLoading ? '…' : '📍 Calcola'}</Text>
                    </TouchableOpacity>
                  </View>

                  {/* Waste types */}
                  <Text style={styles.binLabel}>Tipi di rifiuto</Text>
                  {binWasteTypes.map((val, i) => (
                    <WasteDropdown
                      key={i}
                      value={val}
                      options={optionsForSlot(i)}
                      placeholder={i === 0 ? 'Tipo principale…' : 'Tipo aggiuntivo…'}
                      onSelect={(opt) => setWasteAt(i, opt)}
                    />
                  ))}

                  {/* + add another waste type */}
                  {canAddMoreWaste && (
                    <TouchableOpacity style={styles.binAddWasteBtn} activeOpacity={0.8} onPress={addWasteSlot}>
                      <Text style={styles.binAddWasteTxt}>＋</Text>
                    </TouchableOpacity>
                  )}

                  {/* Collection center in this neighbourhood (only if any exists) */}
                  {centersInZone.length > 0 ? (
                    <>
                      <Text style={styles.binLabel}>Centro di raccolta ({pendingZone})</Text>
                      <WasteDropdown
                        value={centersInZone.find(c => c._id === binCenterId)?.name || ''}
                        options={centersInZone.map(c => c.name)}
                        placeholder="Seleziona un centro…"
                        onSelect={(name) => {
                          const c = centersInZone.find(x => x.name === name);
                          setBinCenterId(c?._id || '');
                        }}
                      />
                    </>
                  ) : (
                    <Text style={styles.binMuted}>
                      Nessun centro di raccolta in questo quartiere: il bidone resterà non
                      assegnato (stato GUASTO) finché non verrà creato un centro qui.
                    </Text>
                  )}
                </ScrollView>

                {/* Add bin button */}
                <TouchableOpacity
                  style={[styles.binSubmitBtn, !canAddBin && styles.binSubmitBtnDisabled]}
                  activeOpacity={canAddBin ? 0.85 : 1}
                  onPress={addBin}
                >
                  <Text style={styles.binSubmitTxt}>{savingBin ? 'Aggiunta…' : 'Aggiungi cassone'}</Text>
                </TouchableOpacity>
              </View>
            </View>
          )}

          {/* Step 2b — collection center configuration popup */}
          {pendingCoord && creationType === 'center' && (
            <View style={styles.binOverlay}>
              <TouchableOpacity style={styles.binBackdrop} activeOpacity={1} onPress={() => {}} />
              <View style={styles.binCard}>
                {/* Header */}
                <View style={styles.binHeader}>
                  <Text style={styles.binTitle}>Nuovo centro di raccolta</Text>
                  <TouchableOpacity style={styles.binCloseBtn} activeOpacity={0.7} onPress={closePopup}>
                    <Text style={styles.binCloseTxt}>✕</Text>
                  </TouchableOpacity>
                </View>

                <ScrollView style={{ maxHeight: 460 }} showsVerticalScrollIndicator={false}>
                  {/* Name */}
                  <Text style={styles.binLabel}>Nome del centro</Text>
                  <TextInput
                    style={styles.binInput}
                    placeholder="Es. Centro Raccolta Trento Nord"
                    placeholderTextColor="#999"
                    value={centerName}
                    onChangeText={setCenterName}
                  />

                  {/* Address + calculate button */}
                  <Text style={styles.binLabel}>Indirizzo</Text>
                  <View style={styles.binAddressRow}>
                    <TextInput
                      style={[styles.binInput, { flex: 1, marginBottom: 0 }]}
                      placeholder="Indirizzo del centro"
                      placeholderTextColor="#999"
                      value={centerAddress}
                      onChangeText={setCenterAddress}
                    />
                    <TouchableOpacity
                      style={styles.binCalcBtn}
                      activeOpacity={0.8}
                      onPress={calcCenterAddress}
                      disabled={centerAddrLoading}
                    >
                      <Text style={styles.binCalcTxt}>{centerAddrLoading ? '…' : '📍 Calcola'}</Text>
                    </TouchableOpacity>
                  </View>

                  {/* Opening hours (optional → schema default if left empty) */}
                  <Text style={styles.binLabel}>Orari di apertura (opzionale)</Text>
                  <View style={styles.timeRow}>
                    <Text style={styles.timeLabel}>Apertura</Text>
                    <TextInput
                      style={styles.timeInput} placeholder="HH" placeholderTextColor="#999"
                      keyboardType="numeric" maxLength={2} value={openH} onChangeText={setOpenH}
                    />
                    <Text style={styles.timeColon}>:</Text>
                    <TextInput
                      style={styles.timeInput} placeholder="MM" placeholderTextColor="#999"
                      keyboardType="numeric" maxLength={2} value={openM} onChangeText={setOpenM}
                    />
                  </View>
                  <View style={styles.timeRow}>
                    <Text style={styles.timeLabel}>Chiusura</Text>
                    <TextInput
                      style={styles.timeInput} placeholder="HH" placeholderTextColor="#999"
                      keyboardType="numeric" maxLength={2} value={closeH} onChangeText={setCloseH}
                    />
                    <Text style={styles.timeColon}>:</Text>
                    <TextInput
                      style={styles.timeInput} placeholder="MM" placeholderTextColor="#999"
                      keyboardType="numeric" maxLength={2} value={closeM} onChangeText={setCloseM}
                    />
                  </View>
                  <Text style={styles.binMuted}>
                    Quartiere: {pendingZone || 'Altro'} · coordinate e area sono calcolate dal punto scelto.
                  </Text>
                </ScrollView>

                {/* Add center button */}
                <TouchableOpacity
                  style={[styles.binSubmitBtn, !canAddCenter && styles.binSubmitBtnDisabled]}
                  activeOpacity={canAddCenter ? 0.85 : 1}
                  onPress={addCenter}
                >
                  <Text style={styles.binSubmitTxt}>{savingCenter ? 'Creazione…' : 'Crea centro'}</Text>
                </TouchableOpacity>
              </View>
            </View>
          )}
        </>
      )}

      {/* ── Event-creation map mode: hint + cancel ✕ ── */}
      {eventMode && (
        <>
          {!eventCenter && (
            <View style={styles.placeHintBox} pointerEvents="none">
              <Text style={styles.placeHintText}>
                Click sulla mappa per scegliere il centro dell'evento · rotella per zoom · tasto centrale per spostarti
              </Text>
            </View>
          )}
          <View style={styles.placeCancelWrap} pointerEvents="box-none">
            <TouchableOpacity style={styles.placeCancelBtn} activeOpacity={0.85} onPress={cancelEventCreation}>
              <Text style={styles.placeCancelTxt}>✕</Text>
            </TouchableOpacity>
          </View>
        </>
      )}

      {/* ── Event configuration popup (creation while eventCenter set, or edit) ── */}
      {eventCenter && (eventMode || editingEventId) && (
        <View style={styles.binOverlay}>
          <TouchableOpacity style={styles.binBackdrop} activeOpacity={1} onPress={() => {}} />
          <View style={styles.binCard}>
            <View style={styles.binHeader}>
              <Text style={styles.binTitle}>{editingEventId ? 'Modifica evento' : 'Nuovo evento di raccolta'}</Text>
              <TouchableOpacity style={styles.binCloseBtn} activeOpacity={0.7} onPress={closeEventPopup}>
                <Text style={styles.binCloseTxt}>✕</Text>
              </TouchableOpacity>
            </View>

            <ScrollView style={{ maxHeight: 520 }} showsVerticalScrollIndicator={false} nestedScrollEnabled>
              {/* Name */}
              <Text style={styles.binLabel}>Nome dell'evento</Text>
              <TextInput
                style={styles.binInput}
                placeholder="Es. Settimana del Riciclo"
                placeholderTextColor="#999"
                value={evName}
                onChangeText={setEvName}
              />

              {/* Radius */}
              <Text style={styles.binLabel}>Raggio dell'area (metri)</Text>
              <TextInput
                style={styles.binInput}
                placeholder="Es. 300"
                placeholderTextColor="#999"
                keyboardType="numeric"
                value={evRadius}
                onChangeText={(t) => setEvRadius(t.replace(/[^0-9]/g, ''))}
              />

              {/* Boosted waste types */}
              <Text style={styles.binLabel}>Tipi di rifiuto potenziati</Text>
              {evWasteTypes.map((val, i) => (
                <WasteDropdown
                  key={i}
                  value={val}
                  options={optionsForEvSlot(i)}
                  placeholder={i === 0 ? 'Tipo principale…' : 'Tipo aggiuntivo…'}
                  onSelect={(opt) => setEvWasteAt(i, opt)}
                />
              ))}
              {canAddMoreEvWaste && (
                <TouchableOpacity style={styles.binAddWasteBtn} activeOpacity={0.8} onPress={addEvWasteSlot}>
                  <Text style={styles.binAddWasteTxt}>＋</Text>
                </TouchableOpacity>
              )}

              {/* Boost multiplier */}
              <Text style={styles.binLabel}>Boost punti</Text>
              <View style={styles.boostRow}>
                {EVENT_BOOSTS.map((b) => (
                  <TouchableOpacity
                    key={b}
                    style={[styles.boostBtn, evBoost === b && styles.boostBtnActive]}
                    activeOpacity={0.85}
                    onPress={() => setEvBoost(b)}
                  >
                    <Text style={[styles.boostBtnTxt, evBoost === b && styles.boostBtnTxtActive]}>x{b}</Text>
                  </TouchableOpacity>
                ))}
              </View>

              {/* Start */}
              <Text style={styles.binLabel}>Inizio (giorno · ora · minuto)</Text>
              {evStart && <DateTimeScroller value={evStart} onChange={setEvStart} />}

              {/* End */}
              <Text style={styles.binLabel}>Fine (giorno · ora · minuto)</Text>
              {evEnd && <DateTimeScroller value={evEnd} onChange={setEvEnd} />}
              {evStart && evEnd && evEnd.getTime() <= evStart.getTime() && (
                <Text style={styles.evError}>⚠️ La fine deve essere successiva all'inizio.</Text>
              )}

              <Text style={styles.binMuted}>
                Quartiere: {eventZone || 'Altro'} · l'area sarà un cerchio giallo centrato sul punto scelto.
              </Text>

              {editingEventId && (
                <TouchableOpacity style={styles.binDeleteBtn} activeOpacity={0.85} onPress={deleteEvent}>
                  <Text style={styles.binSubmitTxt}>{savingEvent ? 'Eliminazione…' : 'Elimina evento'}</Text>
                </TouchableOpacity>
              )}
            </ScrollView>

            <TouchableOpacity
              style={[styles.binSubmitBtn, !canSaveEvent && styles.binSubmitBtnDisabled]}
              activeOpacity={canSaveEvent ? 0.85 : 1}
              onPress={saveEvent}
            >
              <Text style={styles.binSubmitTxt}>
                {savingEvent ? 'Salvataggio…' : (editingEventId ? 'Salva modifiche' : 'Crea evento')}
              </Text>
            </TouchableOpacity>
          </View>
        </View>
      )}

      {/* ── Event characteristics (admin left-click on an event, read-only) ── */}
      {viewingEvent && (
        <View style={styles.binOverlay}>
          <TouchableOpacity style={styles.binBackdrop} activeOpacity={1} onPress={() => setViewingEvent(null)} />
          <View style={styles.binCard}>
            <View style={styles.binHeader}>
              <Text style={styles.binTitle} numberOfLines={1}>{viewingEvent.name}</Text>
              <TouchableOpacity style={styles.binCloseBtn} activeOpacity={0.7} onPress={() => setViewingEvent(null)}>
                <Text style={styles.binCloseTxt}>✕</Text>
              </TouchableOpacity>
            </View>
            <View style={styles.detailRow}>
              <Text style={styles.detailLabel}>Inizio</Text>
              <Text style={styles.detailValue}>{formatEventDateTime(viewingEvent.startDate)}</Text>
            </View>
            <View style={styles.detailRow}>
              <Text style={styles.detailLabel}>Fine</Text>
              <Text style={styles.detailValue}>{formatEventDateTime(viewingEvent.endDate)}</Text>
            </View>
            <View style={styles.detailRow}>
              <Text style={styles.detailLabel}>Raggio</Text>
              <Text style={styles.detailValue}>{viewingEvent.radius} m</Text>
            </View>
            <View style={styles.detailRow}>
              <Text style={styles.detailLabel}>Boost punti</Text>
              <Text style={[styles.detailValue, { color: PRIMARY, fontWeight: '800' }]}>x{viewingEvent.boost}</Text>
            </View>
            <View style={styles.detailRow}>
              <Text style={styles.detailLabel}>Rifiuti potenziati</Text>
              <Text style={styles.detailValue}>{(viewingEvent.wasteTypes || []).join(', ') || '—'}</Text>
            </View>
            <Text style={styles.binMuted}>Click destro sull'evento per modificarne i parametri.</Text>
          </View>
        </View>
      )}

      {/* ── Circoscrizione statistics popup (left-click on a zone) ── */}
      {statsZone && (() => {
        const s = statsForZone(statsZone);
        const leftColumn = [
          { label: 'Bidoni totali',     value: s.totalBins },
          { label: 'Bidoni operativi',  value: s.operationalBins },
          { label: 'Sensori attivi',    value: s.activeSensors },
          { label: 'Centri di Raccolta', value: s.recyclingCenters },
        ];
        const rightColumn = [
          { label: 'Cittadini',     value: s.citizens },
          { label: 'Operatori',     value: s.operators },
          { label: 'Eventi attivi', value: s.activeEvents },
          { label: 'Segnalazioni',  value: s.segnalazioni },
        ];
        const renderColumn = (rows) => rows.map((r) => (
          <View key={r.label} style={styles.statRow}>
            <Text style={styles.statValue}>{r.value}</Text>
            <Text style={styles.statLabel}>{r.label}</Text>
          </View>
        ));
        return (
          <View style={styles.statsOverlay}>
            {/* Backdrop — clicking outside the card closes the popup */}
            <TouchableOpacity
              style={styles.statsBackdrop}
              activeOpacity={1}
              onPress={() => setStatsZone(null)}
            />
            <View style={styles.statsCard}>
              {/* Header: close button on the left, zone name as title */}
              <View style={styles.statsHeader}>
                <Text style={styles.statsTitle} numberOfLines={1}>{statsZone}</Text>
                <View style={styles.statsCloseBtn} />{/* spacer to keep title centred */}
                <TouchableOpacity
                  onPress={() => setStatsZone(null)}
                  style={styles.statsCloseBtn}
                  activeOpacity={0.7}
                >
                  <Text style={styles.statsCloseTxt}>✕</Text>
                </TouchableOpacity>
              </View>

              {/* Body: two columns */}
              <View style={styles.statsBody}>
                <View style={styles.statsCol}>{renderColumn(leftColumn)}</View>
                <View style={styles.statsColDivider} />
                <View style={styles.statsCol}>{renderColumn(rightColumn)}</View>
              </View>
            </View>
          </View>
        );
      })()}
    </View>
  );
}

